-- 0089: live sessions per batch + per-person attendance marks.
-- batch_sessions: one row per live session of a batch (landing page). Times are stored
-- as timestamptz; the app shows PKT. public_code is generated by the app.
-- batch_session_marks: one row per (session, person) present. Service-role only: RLS on,
-- zero policies (same convention as 0077 / 0088). The older attendance_sessions /
-- attendance_events tables are unrelated legacy and are not touched.
-- Also: landing_pages.attendance_min_pct, participant_sends session columns, and
-- pz_merge_people now moves marks too. Safe to re-run.

-- ------------------------------------------------------------ tables
create table if not exists public.batch_sessions (
  id                      uuid primary key default gen_random_uuid(),
  page_id                 uuid not null references public.landing_pages (id) on delete cascade,
  number                  int not null check (number >= 1),
  title                   text not null default '',
  starts_at               timestamptz not null,
  zoom_url                text not null default '',
  kahoot_url              text not null default '',
  include_kahoot          boolean not null default false,
  include_attendance_link boolean not null default true,
  window_override         text not null default 'auto' check (window_override in ('auto','open','closed')),
  email_enabled           boolean not null default true,
  email_lead_minutes      int not null default 60 check (email_lead_minutes between 0 and 10080),
  public_code             text not null unique,
  created_at              timestamptz default now(),
  unique (page_id, number)
);
create index if not exists batch_sessions_page_starts_idx
  on public.batch_sessions (page_id, starts_at);

create table if not exists public.batch_session_marks (
  id         uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.batch_sessions (id) on delete cascade,
  person_id  uuid not null references public.pz_people (id) on delete cascade,
  source     text not null check (source in ('personal','shared','admin')),
  marked_at  timestamptz not null default now(),
  marked_by  uuid references public.profiles (id) on delete set null,
  unique (session_id, person_id)
);
create index if not exists batch_session_marks_person_idx
  on public.batch_session_marks (person_id);

alter table public.batch_sessions enable row level security;
alter table public.batch_session_marks enable row level security;

-- ------------------------------------------------------------ new columns
alter table public.landing_pages
  add column if not exists attendance_min_pct int not null default 75
  check (attendance_min_pct between 0 and 100);

alter table public.participant_sends
  add column if not exists session_id uuid references public.batch_sessions (id) on delete set null;
alter table public.participant_sends
  add column if not exists session_kind text check (session_kind in ('reminder','update'));

do $$
begin
  if not exists (
    select 1 from pg_constraint
     where conname = 'participant_sends_session_pair_chk'
       and conrelid = 'public.participant_sends'::regclass
  ) then
    alter table public.participant_sends
      add constraint participant_sends_session_pair_chk
      check ((session_id is null) = (session_kind is null));
  end if;
end;
$$;

-- one automatic reminder per session; update emails are not limited here
create unique index if not exists participant_sends_reminder_key
  on public.participant_sends (session_id) where session_kind = 'reminder';

-- ------------------------------------------------------------ merge
-- Folds person p_drop into p_keep. The dropped PZ ID stays valid as an alias.
-- Attendance marks move too; a session the kept person already has keeps their mark.
create or replace function public.pz_merge_people(p_keep uuid, p_drop uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if p_keep is null or p_drop is null then
    raise exception 'pz_merge_people: both ids are required';
  end if;
  if p_keep = p_drop then
    raise exception 'pz_merge_people: cannot merge a person into itself';
  end if;
  -- lock both rows, lower uuid first, so concurrent merges cannot deadlock
  perform 1
    from public.pz_people
   where id in (p_keep, p_drop)
   order by id
     for update;
  if not exists (select 1 from public.pz_people where id = p_keep)
     or not exists (select 1 from public.pz_people where id = p_drop) then
    raise exception 'pz_merge_people: person not found';
  end if;

  update public.pz_person_emails set person_id = p_keep where person_id = p_drop;
  update public.pz_id_aliases set person_id = p_keep where person_id = p_drop;
  update public.landing_registrations set person_id = p_keep where person_id = p_drop;

  insert into public.batch_session_marks (session_id, person_id, source, marked_at, marked_by)
  select session_id, p_keep, source, marked_at, marked_by
    from public.batch_session_marks
   where person_id = p_drop
  on conflict do nothing;
  delete from public.batch_session_marks where person_id = p_drop;

  delete from public.pz_people where id = p_drop;
end;
$$;

revoke all on function public.pz_merge_people(uuid, uuid) from public, anon, authenticated;
grant execute on function public.pz_merge_people(uuid, uuid) to service_role;
